        "dosage":  "anjing: Otic: 4–8 drops (tergantung BB hewan) ke dalam telinga yang bermasalah, atau oleskan salep pada area yang bermasalah tiap 12 jam. Easotic preparation: aplikasikan\n1 ml ke setiap telinga setiap 24 jam menggunakan sistem pemberian dosis terukur atau dosis tunggal..\n• Ophthalmic: 1 drop per mata q6–8h. 1 cm gel per mata q8–12h.\n• Sistemik: 5–10 mg/kg secara perlahan i.v. (over 30 min), i.m., s.c. q24h.  kucing : Ophthalmic: Dose as for Anjing.\n• Sistemik: 5–8 mg/kg secara perlahan i.v. (over 30 min), i.m., s.c. q24h. Kuda: 7.7 – 9.7 mg/kg IV sekali sehari, Infeksi uterus melalui infus intrauterin: 2 – 2,5 g (20 – 25 mL) dilarutkan dalam 200 – 500 mL larutan saline normal steril, lalu diinfuskan secara aseptik ke dalam uterus 1xi sehari selama 3 - 5 hari selama masa estrus. Ferret:  5 – 8 mg/kg IV, IM, or SC 1x sehari; Birds: 5 – 10 mg/kg IM tiap 12 jam; Kelinci: 5 – 8 mg/kg 1x sehari atau dibagi tiap 8 - 24 jam, SC, IM, or IV; ROden dan small mammals: 2 – 4 mg/kg SC or IM tiap 8-24 jam; Reptil: 5 – 10 mg/kg/hari; Primata: 2-3 mg/kg\nIM, IV q12h selama 5-7 hari; Ikan: Goldfish, toadfish, 3.5 mg/kg IM\nq24h; Ampibi: 2-4 mg/kg IM q72h × 4 pengobatan",
        "indication":  "Aminoglikosida bakterisida konsentrasi-dependent untuk Gram-negatif dan beberapa Gram-positif (Staph, Pseudomonas, R. equi); terapi empiris infeksi berat bersama penisilin/metronidazol.",
        "restrictions":  "Kontra: gendang telinga perforasi (sediaan otic), nefrotoksik lain, \u003e7 hari systemic. Adverse: nefrotoksisitas, ototoksisitas, blok neuromuskular, tunda healing ulkus kornea. Interaksi: hindari nefro/ototoksik (amphotericin B, furosemide), inaktivasi dengan beta-laktam/heparin in vitro, potensi blok neuromuskular. Kategori EMA C (Caution).",
        "amegCategory":  "Kategori EMA C (Caution).",
