        "dosage":  "anjing, kucing: Terapi cairan: kebutuhan cairan bergantung pada tingkat dehidrasi dan kehilangan cairan yang terus berlangsung. 0.45-3% solutions 50-60 ml/kg/hari i.v./p.o. (uncomplicated); defisit: 0.9-3% NaCl; maintenance: 0.45% NaCl (+K), Hypotension/shock: 5–7.5% NaCl solutions (hypertonic saline) at doses of 3–8 ml/kg i.v. , Salt-wasting syndromes (hypoadrenocorticism): 1–5 g p.o. q24h. Corneal oedema: apply a small amount of ointment q4–24h.; Fish: 1-5 g/L tank water (profilaksis atau terapi ektoparasit); Amphibians: 6 g/L × 5-10 min bath q24h × 3-5 days (ektoparasit protozoa); Reptile: PO, SC, IV, IO, ICe, EpiCe, prn (NaCl 0.45%, hypertonic dehydration)",
        "indication":  "Penggantian cairan intravena merupakan terapi pilihan bagi pasien dengan hiperkalsemia atau alkalosis hiperkloremik. Larutan natrium klorida sering digunakan sebagai pelarut obat. Salin hipertonik digunakan untuk meningkatkan volume darah yang bersirkulasi secara cepat pada hewan yang mengalami syok, khususnya selama periode pra-operasi. Salep mata hipertonik digunakan dalam penanganan edema kornea. Suplementasi natrium oral direkomendasikan untuk penanganan jangka panjang hipoadrenokortisisme. Pada Exotic untuk terapi ektoparasit",
        "restrictions":  "Salin hipertonik tidak boleh diberikan kepada hewan yang mengalami dehidrasi, dan larutan hipotonik tidak boleh diberikan kepada hewan yang mengalami hipovolemia.",
