        "indication":  "Prokinetik GI via reseptor 5-HT4 pada neuron kolinergik enterik, depolariasi \u0026 kontraksi otot polos; berguna untuk motilitas lambung menurun, konstipasi \u0026 megakolon ringan-sedang pada kucing, meningkatkan tekanan sfingter esofagus bawah pada anjing",
        "restrictions":  "Kontraindikasi: obstruksi/perforasi GI. Reaksi: muntah, diare, nyeri abdomen; pada manusia prolongasi QT \u0026 aritmia serius (belum dilaporkan pada anjing/kucing). Interaksi: metabolisme CYP450 (hati-hati dengan ketoconazole, itraconazole, cimetidine, amiodarone, chloramphenicol), obat pemanjang QT (amiodarone, procainamide, quinidine, sotalol, TCA) meningkatkan risiko.",
